-- User ENV overrides (auto-generated).
-- Add values using: hl.env("KEY", "VALUE")
-- Example:
-- hl.env("MOZ_ENABLE_WAYLAND", "1")

-- Converted from ENVariables.conf
hl.env("__GL_YIELD", "USLEEP")

-- GPU mode (replaces UserConfigs/GpuMode.conf generated by ~/.zprofile).
-- ~/.zprofile still exports AQ_DRM_DEVICES before Hyprland starts (aquamarine
-- reads it before any config loads), e.g. "/dev/dri/card1:/dev/dri/card0".
-- NVIDIA PCI card: /dev/dri/by-path/pci-0000:01:00.0-card
-- Must return "nvidia" when NVIDIA is the primary renderer, else "mesa".
local function glx_vendor()
  -- Single source of truth: whatever GPU ~/.zprofile put first in AQ_DRM_DEVICES.
  -- Unset (nested/other session) -> mesa, matches aquamarine's default (boot_vga Intel).
  local primary = (os.getenv("AQ_DRM_DEVICES") or ""):match("^[^:]+")
  if not primary then return "mesa" end
  local p = io.popen("readlink -f /dev/dri/by-path/pci-0000:01:00.0-card")
  local nv = p and p:read("*l") or ""
  if p then p:close() end
  return (nv ~= "" and primary == nv) and "nvidia" or "mesa"
end

hl.env("__GLX_VENDOR_LIBRARY_NAME", glx_vendor())
hl.env("LIBVA_DRIVER_NAME", "iHD") -- video decode stays on Intel in both modes
